"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["2509"],{32101(e){e.exports=JSON.parse('{"id":"V4-192","slug":"world-trade-organization","term":"World Trade Organization (WTO)","also_known_as":[],"difficulty":"Intermediate","definition":"The World Trade Organization (WTO) is an international organisation that sets and enforces rules for trade between nations, provides a forum for trade negotiations and helps resolve trade disputes.","explanation":["The WTO was established in 1995, replacing the General Agreement on Tariffs and Trade, which had governed international trade since 1948. It is based in Geneva and has 166 members, covering the large majority of world trade.","The WTO\u2019s agreements cover trade in goods, services and intellectual property. Key principles include non-discrimination, where members should not discriminate between trading partners or between foreign and domestic products; lowering trade barriers through negotiation; and predictability, through binding commitments on tariffs.","The WTO\u2019s dispute settlement system allows members to bring complaints when they believe others have broken trade rules. Its Appellate Body, which heard appeals, stopped functioning in 2019 because the United States blocked the appointment of new members, weakening the system.","For example, if one country believes another is unfairly subsidising its exports, it can bring a case at the WTO, and if successful, may be authorised to impose retaliatory tariffs.","Decisions at the WTO are generally made by consensus, which can make reaching new agreements slow. Rising trade tensions and tariffs have challenged its role in recent years."],"note":"","total":1725,"prev":{"slug":"world-bank","term":"World Bank"},"next":{"slug":"worst-case-scenario","term":"Worst-Case Scenario"}}')}}]);